#!/usr/bin/env python3
"""audit_policy.py — Audit a NemoClaw sandbox policy YAML for security issues.

Reads a policy YAML file and checks for common security misconfigurations.
Produces a report with CRITICAL, WARNING, and INFO severity levels.

Exit codes:
    0 — No critical issues found.
    1 — One or more critical issues found.

Usage:
    python scripts/audit_policy.py <policy.yaml>
"""

import sys
from dataclasses import dataclass, field
from pathlib import Path
from typing import List

import yaml


@dataclass
class Finding:
    severity: str
    category: str
    message: str


@dataclass
class AuditReport:
    findings: List[Finding] = field(default_factory=list)

    def critical(self, category: str, message: str) -> None:
        self.findings.append(Finding("CRITICAL", category, message))

    def warning(self, category: str, message: str) -> None:
        self.findings.append(Finding("WARNING", category, message))

    def info(self, category: str, message: str) -> None:
        self.findings.append(Finding("INFO", category, message))

    @property
    def has_critical(self) -> bool:
        return any(f.severity == "CRITICAL" for f in self.findings)

    def render(self) -> str:
        if not self.findings:
            return "No issues found. Policy passes all audit checks."

        order = {"CRITICAL": 0, "WARNING": 1, "INFO": 2}
        sorted_f = sorted(self.findings, key=lambda f: order.get(f.severity, 99))

        counts = {"CRITICAL": 0, "WARNING": 0, "INFO": 0}
        for f in self.findings:
            counts[f.severity] = counts.get(f.severity, 0) + 1

        lines = [
            "=== NemoClaw Policy Audit Report ===",
            "",
            f"Summary: {counts['CRITICAL']} critical, "
            f"{counts['WARNING']} warning, {counts['INFO']} info",
            "",
        ]
        for f in sorted_f:
            lines.append(f"[{f.severity}] ({f.category}) {f.message}")
        lines.append("")

        if self.has_critical:
            lines.append("Result: FAIL — critical issues must be resolved before deployment.")
        else:
            lines.append("Result: PASS — no critical issues found.")

        return "\n".join(lines)


SENSITIVE_PATHS = ("/etc", "/usr", "/lib", "/proc")
SHELL_BINARIES = ("/bin/sh", "/bin/bash", "/usr/bin/sh", "/usr/bin/bash")


def check_filesystem(policy: dict, report: AuditReport) -> None:
    fs = policy.get("filesystem_policy")
    if fs is None:
        report.warning("filesystem", "No filesystem_policy found.")
        return
    if not isinstance(fs, dict):
        report.warning("filesystem", "filesystem_policy is not a mapping.")
        return

    rw_paths = fs.get("read_write", [])
    if isinstance(rw_paths, list):
        for p in rw_paths:
            if isinstance(p, str):
                for sensitive in SENSITIVE_PATHS:
                    if p == sensitive or p.startswith(sensitive + "/"):
                        report.critical(
                            "filesystem",
                            f"Read-write access on sensitive path '{p}'. "
                            f"Never grant read-write to {sensitive}.",
                        )


def check_landlock(policy: dict, report: AuditReport) -> None:
    landlock = policy.get("landlock")
    if landlock is None:
        report.critical(
            "landlock",
            "No landlock configuration. Always include landlock with best_effort compatibility.",
        )
        return
    if not isinstance(landlock, dict):
        report.warning("landlock", "landlock is not a mapping.")
        return

    compat = landlock.get("compatibility")
    if compat is None:
        report.warning("landlock", "No compatibility mode set. Use best_effort.")


def check_process(policy: dict, report: AuditReport) -> None:
    process = policy.get("process")
    if process is None:
        report.warning("process", "No process configuration found.")
        return
    if not isinstance(process, dict):
        report.warning("process", "process is not a mapping.")
        return

    user = process.get("run_as_user")
    if user is None:
        report.critical(
            "process",
            "No run_as_user specified. Always run as non-root sandbox user.",
        )
    elif user in ("root", "0"):
        report.critical(
            "process",
            f"Process runs as '{user}'. Always run as non-root sandbox user.",
        )


def check_network_policies(policy: dict, report: AuditReport) -> None:
    net = policy.get("network_policies")
    if net is None:
        report.info("network", "No network_policies key — sandbox has no network access.")
        return
    if not isinstance(net, dict):
        report.warning("network", "network_policies should be a mapping of named policy blocks.")
        return

    if len(net) == 0:
        report.info("network", "network_policies is empty — sandbox has no network access (may be intentional).")
        return

    for key, block in net.items():
        if not isinstance(block, dict):
            report.warning("network", f"Policy block '{key}' is not a mapping.")
            continue

        endpoints = block.get("endpoints", [])
        if not isinstance(endpoints, list):
            continue

        for i, ep in enumerate(endpoints):
            if not isinstance(ep, dict):
                continue

            host = ep.get("host", "")
            prefix = f"{key}.endpoints[{i}] ({host})"

            # Wildcard hostnames
            if host in ("*", "0.0.0.0"):
                report.critical(
                    "network",
                    f"{prefix}: Wildcard hostname '{host}'. Restrict to specific hosts.",
                )

            # Missing TLS on port 443
            port = ep.get("port")
            tls = ep.get("tls")
            if port == 443 and tls is None:
                report.warning(
                    "network",
                    f"{prefix}: Port 443 without explicit tls field. Add tls: terminate.",
                )

            # Audit mode instead of enforce
            enforcement = ep.get("enforcement")
            if enforcement == "audit":
                report.warning(
                    "network",
                    f"{prefix}: Enforcement is 'audit' not 'enforce'. Use 'enforce' in production.",
                )

            # Full access grants
            access = ep.get("access")
            if access == "full":
                report.warning(
                    "network",
                    f"{prefix}: 'access: full' grants all methods and paths. "
                    "Consider using explicit rules to restrict to required methods.",
                )
            elif access == "read-write":
                report.warning(
                    "network",
                    f"{prefix}: read-write access. Prefer read-only unless writes are needed.",
                )

            # Wildcard methods in rules
            rules = ep.get("rules", [])
            if isinstance(rules, list):
                for j, rule in enumerate(rules):
                    if not isinstance(rule, dict):
                        continue
                    allow = rule.get("allow", {})
                    if isinstance(allow, dict):
                        method = allow.get("method", "")
                        if method == "*":
                            report.info(
                                "network",
                                f"{prefix} rule[{j}]: Wildcard method '*' allows all HTTP methods. "
                                "Consider restricting to specific methods (GET, POST, etc.).",
                            )

        # Shell binaries with network access
        binaries = block.get("binaries", [])
        if isinstance(binaries, list):
            for b in binaries:
                path = b.get("path", "") if isinstance(b, dict) else ""
                if path in SHELL_BINARIES:
                    report.critical(
                        "network",
                        f"{key}: Shell binary '{path}' has network access. Use specific tools instead.",
                    )

        # Policy block with no binaries restriction
        if not binaries:
            report.warning(
                "network",
                f"{key}: No binaries restriction. Any process in the sandbox can use this policy. "
                "Add a binaries list to restrict network access to specific tools.",
            )


def check_duplicate_endpoints(policy: dict, report: AuditReport) -> None:
    """Flag the same host:port appearing in multiple policy blocks."""
    net = policy.get("network_policies")
    if not isinstance(net, dict):
        return

    seen: dict = {}  # (host, port) -> list of policy keys
    for key, block in net.items():
        if not isinstance(block, dict):
            continue
        for ep in block.get("endpoints", []):
            if not isinstance(ep, dict):
                continue
            pair = (ep.get("host", ""), ep.get("port", 0))
            seen.setdefault(pair, []).append(key)

    for (host, port), keys in seen.items():
        if len(keys) > 1:
            report.info(
                "network",
                f"Endpoint {host}:{port} appears in multiple policies: {', '.join(keys)}. "
                "Verify this duplication is intentional.",
            )


def audit_policy(policy: dict) -> AuditReport:
    report = AuditReport()
    check_filesystem(policy, report)
    check_landlock(policy, report)
    check_process(policy, report)
    check_network_policies(policy, report)
    check_duplicate_endpoints(policy, report)
    return report


def main() -> None:
    if len(sys.argv) != 2:
        print(f"Usage: {sys.argv[0]} <policy.yaml>", file=sys.stderr)
        sys.exit(1)

    path = Path(sys.argv[1])
    if not path.is_file():
        print(f"ERROR: File not found: {path}", file=sys.stderr)
        sys.exit(1)

    try:
        with open(path) as f:
            policy = yaml.safe_load(f)
    except yaml.YAMLError as e:
        print(f"ERROR: Failed to parse YAML: {e}", file=sys.stderr)
        sys.exit(1)

    if not isinstance(policy, dict):
        print("ERROR: Policy must be a YAML mapping.", file=sys.stderr)
        sys.exit(1)

    report = audit_policy(policy)
    print(report.render())
    sys.exit(1 if report.has_critical else 0)


if __name__ == "__main__":
    main()
